n = int(input())
ids = []
for i in range(n):
    ids.append(int(input()))

distinct = sorted(set(ids))
print("不重复的号码有", len(distinct), "个喵")
for x in distinct:
    print(x)

repeated = 0
for x in distinct:
    if ids.count(x) > 1:
        repeated = repeated + 1
print("重号的有", repeated, "个喵")
